#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353LL;

long long modInverse(long long a, long long m) {
    long long result = 1;
    long long base = a % m;
    long long exp = m - 2;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % m;
        base = (base * base) % m;
        exp >>= 1;
    }
    return result;
}

long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

long long nCr(int a, int b, vector<long long>& fact, vector<long long>& invFact) {
    return (((fact[b] * invFact[a]) % MOD) * invFact[b - a]) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    long long lmao;
    cin >> N >> lmao;
    if (lmao >= N) {
        cout << 0 << "\n";
    } else {
        int K = (int) lmao;
        int C = N - K;
        vector<long long> factArr(200001);
        vector<long long> invFactArr(200001);
        factArr[0] = 1;
        invFactArr[0] = 1;
        for (int i = 1; i <= 200000; i++) {
            factArr[i] = (factArr[i - 1] * i) % MOD;
            invFactArr[i] = modInverse(factArr[i], MOD);
        }
        long long res = power(C, N, MOD);
        for (int e = 1; e < C; e++) {
            long long temp = power(C - e, N, MOD);
            temp = (temp * nCr(e, C, factArr, invFactArr)) % MOD;
            if (e % 2 == 1)
                res = (res - temp + MOD) % MOD;
            else
                res = (res + temp) % MOD;
        }
        res = (res * nCr(C, N, factArr, invFactArr)) % MOD;
        if (K > 0)
            res = (2 * res) % MOD;
        cout << res << "\n";
    }
    return 0;
}
